{"command": "cd /tmp/sv-963ec6608fe44b6f8d06ee4839a8bd4e

# Use nm to look up symbols at the given PC offsets from the tombstone
# The offsets are: 0x222098, 0x2241ac, 0x1abc80, 0x1abd14, 0x16dfa4, 0x16db6c, 0x16de04
# These are in the .text section. Let's use the dynamic symbol table since it's stripped.

# Extract dynamic symbols sorted by address
nm -D --defined-only libmonosgen-2.0.so.sym 2>/dev/null | sort > /tmp/sv-963ec6608fe44b6f8d06ee4839a8bd4e/syms.txt

# Now find the function for each offset
for offset in 0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04; do
    # Find the last symbol with address <= offset
    result=$(awk -v target="$offset" '
    BEGIN { target_dec = strtonum(target) }
    {
        addr = strtonum("0x" $1)
        if (addr <= target_dec) { best_addr = $1; best_name = $3; best_type = $2 }
    }
    END { if (best_name != "") printf "0x%s %s (offset +0x%x)\n", best_addr, best_name, target_dec - strtonum("0x" best_addr) }
    ' syms.txt)
    echo "  pc $offset -> $result"
done", "description": "Symbolicate PC offsets using dynamic symbols"}
